135	  private static String canonicalizeForPath(String input, boolean alreadyEncoded) {
136	    int codePoint;
137	    for (int i = 0, limit = input.length(); i < limit; i += Character.charCount(codePoint)) {
138	      codePoint = input.codePointAt(i);
139	      if (codePoint < 0x20
140	          || codePoint >= 0x7f
141	          || PATH_SEGMENT_ALWAYS_ENCODE_SET.indexOf(codePoint) != -1
142	          || (!alreadyEncoded && (codePoint == '/' || codePoint == '%'))) {
143	        // Slow path: the character at i requires encoding!
144	        Buffer out = new Buffer();
145	        out.writeUtf8(input, 0, i);
146	        canonicalizeForPath(out, input, i, limit, alreadyEncoded);
147	        return out.readUtf8();
148	      }
149	    }
150	
151	    // Fast path: no characters required encoding.
152	    return input;
153	  }
