155	  private static void canonicalizeForPath(
156	      Buffer out, String input, int pos, int limit, boolean alreadyEncoded) {
157	    Buffer utf8Buffer = null; // Lazily allocated.
158	    int codePoint;
159	    for (int i = pos; i < limit; i += Character.charCount(codePoint)) {
160	      codePoint = input.codePointAt(i);
161	      if (alreadyEncoded
162	          && (codePoint == '\t' || codePoint == '\n' || codePoint == '\f' || codePoint == '\r')) {
163	        // Skip this character.
164	      } else if (codePoint < 0x20
165	          || codePoint >= 0x7f
166	          || PATH_SEGMENT_ALWAYS_ENCODE_SET.indexOf(codePoint) != -1
167	          || (!alreadyEncoded && (codePoint == '/' || codePoint == '%'))) {
168	        // Percent encode this character.
169	        if (utf8Buffer == null) {
170	          utf8Buffer = new Buffer();
171	        }
172	        utf8Buffer.writeUtf8CodePoint(codePoint);
173	        for (long j = 0, size = utf8Buffer.size(); j < size; j++) {
174	          int b = utf8Buffer.getByte(j) & 0xff;
175	          out.writeByte('%');
176	          out.writeByte(HEX_DIGITS[(b >> 4) & 0xf]);
177	          out.writeByte(HEX_DIGITS[b & 0xf]);
178	        }
179	        utf8Buffer.clear();
180	      } else {
181	        // This character doesn't need encoding. Just copy it over.
182	        out.writeUtf8CodePoint(codePoint);
183	      }
184	    }
