16	package retrofit2.adapter.guava;
17	
18	import com.google.common.util.concurrent.AbstractFuture;
19	import com.google.common.util.concurrent.ListenableFuture;
20	import java.io.IOException;
21	import java.lang.annotation.Annotation;
22	import java.lang.reflect.ParameterizedType;
23	import java.lang.reflect.Type;
24	import javax.annotation.Nullable;
25	import retrofit2.Call;
26	import retrofit2.CallAdapter;
27	import retrofit2.Callback;
28	import retrofit2.Response;
29	import retrofit2.Retrofit;
30	
31	/**
32	 * A {@linkplain CallAdapter.Factory call adapter} which creates Guava futures.
33	 *
34	 * <p>Adding this class to {@link Retrofit} allows you to return {@link ListenableFuture} from
35	 * service methods.
36	 *
37	 * <pre><code>
38	 * interface MyService {
39	 *   &#64;GET("user/me")
40	 *   ListenableFuture&lt;User&gt; getUser()
41	 * }
42	 * </code></pre>
43	 *
44	 * There are two configurations supported for the {@code ListenableFuture} type parameter:
45	 *
46	 * <ul>
47	 *   <li>Direct body (e.g., {@code ListenableFuture<User>}) returns the deserialized body for 2XX
48	 *       responses, sets {@link retrofit2.HttpException HttpException} errors for non-2XX responses,
49	 *       and sets {@link IOException} for network errors.
50	 *   <li>Response wrapped body (e.g., {@code ListenableFuture<Response<User>>}) returns a {@link
51	 *       Response} object for all HTTP responses and sets {@link IOException} for network errors
52	 * </ul>
53	 */
54	public final class GuavaCallAdapterFactory extends CallAdapter.Factory {
55	  public static GuavaCallAdapterFactory create() {
56	    return new GuavaCallAdapterFactory();
57	  }
58	
59	  private GuavaCallAdapterFactory() {}
60	
61	  @Override
62	  public @Nullable CallAdapter<?, ?> get(
63	      Type returnType, Annotation[] annotations, Retrofit retrofit) {
64	    if (getRawType(returnType) != ListenableFuture.class) {
65	      return null;
66	    }
67	    if (!(returnType instanceof ParameterizedType)) {
68	      throw new IllegalStateException(
69	          "ListenableFuture return type must be parameterized"
70	              + " as ListenableFuture<Foo> or ListenableFuture<? extends Foo>");
71	    }
72	    Type innerType = getParameterUpperBound(0, (ParameterizedType) returnType);
73	
74	    if (getRawType(innerType) != Response.class) {
75	      // Generic type is not Response<T>. Use it for body-only adapter.
76	      return new BodyCallAdapter<>(innerType);
77	    }
78	
79	    // Generic type is Response<T>. Extract T and create the Response version of the adapter.
80	    if (!(innerType instanceof ParameterizedType)) {
81	      throw new IllegalStateException(
82	          "Response must be parameterized" + " as Response<Foo> or Response<? extends Foo>");
83	    }
84	    Type responseType = getParameterUpperBound(0, (ParameterizedType) innerType);
85	    return new ResponseCallAdapter<>(responseType);
